"""Reader-facing result, primary-source comparison and standalone scientific figure."""
import json, math, csv
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from common import R, read, dump, sha, now, state

def figure():
    groups = read('raw/LITERATURE_GROUPS.json')
    r2 = read('raw/MATCHED_R2.json')
    r3 = read('raw/R3_DOUBLE_RATIO.json')['targets']
    f = read('FROZEN_PREDICTIONS.json')
    (fig, ax) = plt.subplots(1, 3, figsize=(14, 4.5), constrained_layout=True)
    colors = {'PMC10817558': '#285f9e', 'PMC10934854': '#339980', 'PMC6642729': '#ba673a'}
    for (study, color) in colors.items():
        rr = [r for r in groups if r['eligible_R1'] and r['study'] == study and (r['material'] == '3Y')]
        ax[0].errorbar([r['thickness_mm'] for r in rr], [r['mean_N'] / 1000 for r in rr], yerr=[r['sd_N'] / 1000 for r in rr], fmt='o', color=color, label=study.replace('PMC', 'PMC '), alpha=0.85)
    ax[0].set(xlabel='Nominal crown thickness (mm)', ylabel='Published group mean ± specimen SD (kN)', title='Primary 3Y force measurements')
    ax[0].legend(fontsize=8)
    ax[0].grid(alpha=0.2)
    for (i, d) in enumerate(r2['family'][1:]):
        (lo, hi) = d['literature_conditional_prediction']['interval_ratio']
        mid = d['literature_conditional_prediction']['point_ratio']
        ax[1].errorbar(mid, i, xerr=np.array([[mid - lo], [hi - mid]]), fmt='o', color='#ba673a', capsize=4)
    ax[1].set(yticks=[0, 1], yticklabels=['1.0 / 0.8 mm', '1.5 / 0.8 mm'], xlabel='Conditional group force ratio', title='R2 transfer bands remain too wide')
    ax[1].axvline(1, color='grey', ls=':')
    ax[1].grid(alpha=0.2)
    for (i, r) in enumerate(r3):
        (lo, hi) = r['acceptance_window_Q']
        mid = r['Q_FE']
        ax[2].errorbar(mid, i, xerr=np.array([[mid - lo], [hi - mid]]), fmt='o', color='#285f9e', capsize=4)
    ax[2].axvline(1, color='#ba673a', label='Separable thickness control Q=1')
    ax[2].axvspan(math.exp(-0.3), math.exp(0.3), color='#ba673a', alpha=0.12)
    ax[2].set(yticks=[0, 1], yticklabels=['1.0 / 0.8 mm', '1.5 / 0.8 mm'], xlabel='Q: thickness ratio at 30° / ratio at 0°', title='R3 prospective operational test')
    ax[2].legend(fontsize=8)
    ax[2].grid(alpha=0.2)
    fig.suptitle('X1b: absolute transfer UNKNOWN; matched angular contrast can be falsified', fontsize=13)
    fig.text(0.5, -0.04, 'R2: provisional statistical transfer bands. R3: fixed ±0.30 log-error tolerance windows, NOT prediction intervals. No lab test performed.', ha='center', fontsize=9)
    fig.savefig(R / 'crown_loop.png', dpi=160, bbox_inches='tight')
    fig.savefig(R / 'crown_loop.pdf', bbox_inches='tight')
    plt.close(fig)

